#!/usr/bin/env node
/**
 * Build the weekly review from committed daily scorecards instead of scanning
 * R2 raw envelopes. This is the default weekly path: it needs ZERO R2 requests,
 * so the Cloudflare REST API 1,200 req/5min limit cannot break the review.
 *
 * Data source: docs/eval/scorecard-YYYY-MM-DD.json (already generated by the
 * daily job). Missing days are listed and excluded; if no scorecard is found
 * the command fails explicitly (no fabricated/empty report).
 *
 * Usage:
 *   node scripts/weekly-from-scorecards.mjs --since 2026-11-18 --days 7
 *   node scripts/weekly-from-scorecards.mjs --since 2026-11-18 --days 7 --json
 *
 * R2 raw scan remains available only through the explicit workflow input
 * `from_r2=true` (the legacy capture-digest --since path).
 */
import { readFile, writeFile, mkdir, readdir } from 'node:fs/promises';
import { join } from 'node:path';
import { isoWeek, renderWeeklyReview } from './analyze-captures.mjs';

const DATE_RE = /^\d{4}-\d{2}-\d{2}$/;

function argValue(argv, name, fallback = '') {
  return argv.includes(name) ? argv[argv.indexOf(name) + 1] : fallback;
}

function daysBetween(since, days) {
  const start = new Date(`${since}T00:00:00.000Z`);
  if (Number.isNaN(start.getTime())) throw new Error(`invalid --since: ${since}`);
  return Array.from({ length: days }, (_, index) => {
    const date = new Date(start);
    date.setUTCDate(date.getUTCDate() + index);
    return date.toISOString().slice(0, 10);
  });
}

function sumMetrics(rows) {
  const totals = { requests: 0, mcpRequests: 0, errors: 0, truncated: 0, overflow: 0 };
  for (const row of rows) {
    totals.requests += Number(row.requests ?? 0);
    totals.mcpRequests += Number(row.mcpRequests ?? 0);
    totals.errors += Number(row.errors ?? 0);
    totals.truncated += Number(row.truncated ?? 0);
    totals.overflow += Number(row.overflow ?? 0);
  }
  totals.errorRate = totals.requests ? Number((totals.errors / totals.requests).toFixed(4)) : 0;
  return totals;
}

export async function buildWeeklyFromScorecards({
  since, days = 7, docsDir = 'docs/eval', outDir = 'docs/eval', now = new Date(),
}) {
  if (!DATE_RE.test(String(since))) throw new Error(`invalid --since: ${since}`);
  const wanted = daysBetween(since, days);
  const available = new Set((await readdir(docsDir)).filter((name) => /^scorecard-\d{4}-\d{2}-\d{2}\.json$/.test(name)));
  const found = [];
  const missing = [];
  for (const date of wanted) {
    const name = `scorecard-${date}.json`;
    if (!available.has(name)) { missing.push(date); continue; }
    const parsed = JSON.parse(await readFile(join(docsDir, name), 'utf8'));
    const metrics = parsed.metrics ?? {};
    found.push({
      date,
      requests: Number(metrics.requests ?? 0),
      mcpRequests: Number(metrics.mcpRequests ?? 0),
      errors: Number(metrics.errors ?? 0),
      errorRate: Number(metrics.errorRate ?? 0),
      p50Ms: Number(metrics.p50Ms ?? 0),
      p95Ms: Number(metrics.p95Ms ?? 0),
      truncated: Number(metrics.truncated ?? 0),
      overflow: Number(metrics.overflow ?? 0),
    });
  }
  if (!found.length) {
    throw new Error(`NO_SCORECARDS: no docs/eval/scorecard-YYYY-MM-DD.json in ${docsDir} for ${since}+${days}d`);
  }
  const week = isoWeek(found[found.length - 1].date);
  const totals = sumMetrics(found);
  const md = renderWeeklyReview({
    week,
    since,
    days,
    trend: found,
    totals,
    candidates: [],
  });
  const withMissing = missing.length
    ? `${md}\n> Missing scorecards in this window: ${missing.join(', ')}. They are excluded from totals; this is NOT_ENOUGH evidence for those days.\n`
    : md;
  await mkdir(outDir, { recursive: true });
  const path = join(outDir, `weekly-${week}.md`);
  await writeFile(path, withMissing, 'utf8');
  return {
    schema: 'weekly-from-scorecards.v1',
    week,
    since,
    days,
    source: 'docs/eval/scorecard-*.json',
    r2Requests: 0,
    dates: found.map((row) => row.date),
    missing,
    totals,
    path,
  };
}

export async function main(argv = process.argv.slice(2), deps = {}) {
  const { stdout = console.log, stderr = console.error } = deps;
  const since = argValue(argv, '--since');
  const days = Number(argValue(argv, '--days', '7'));
  const docsDir = argValue(argv, '--docs-dir', 'docs/eval');
  const outDir = argValue(argv, '--out-dir', 'docs/eval');
  if (!since || !Number.isFinite(days) || days < 1) {
    stderr('usage: weekly-from-scorecards.mjs --since YYYY-MM-DD [--days 7] [--docs-dir docs/eval] [--out-dir docs/eval] [--json]');
    return 2;
  }
  try {
    const result = await buildWeeklyFromScorecards({ since, days: Math.floor(days), docsDir, outDir });
    if (argv.includes('--json')) stdout(JSON.stringify(result, null, 2));
    else stdout(`[weekly] ${result.path}: ${result.dates.length} scorecards, missing=${result.missing.length}, r2Requests=0`);
    return 0;
  } catch (error) {
    stderr(`[weekly] ${error?.message ?? String(error)}`);
    return 1;
  }
}

const isDirectRun = typeof process.argv[1] === 'string' && /weekly-from-scorecards\.mjs$/.test(process.argv[1]);
if (isDirectRun) {
  main().then((code) => { process.exitCode = code; }).catch((error) => {
    console.error(`[weekly] ${error?.message ?? String(error)}`);
    process.exitCode = 1;
  });
}
